    function scGetColumnOrderRule($fieldName)
    {
        $sortRule = 'nosort';
        if ($_SESSION['sc_session'][$this->Ini->sc_page]['cons_cta_corren_fornec_imp_entregue']['ordem_cmp'] == $fieldName) {
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['cons_cta_corren_fornec_imp_entregue']['ordem_label'] == 'desc') {
                $sortRule = 'desc';
            } else {
                $sortRule = 'asc';
            }
        }
        return $sortRule;
    }

    function scGetColumnOrderIcon($fieldName, $sortRule, $skipUnusedClass = false)
    {
        $unusedClass = $skipUnusedClass ? '' : ' sc-grid-order-icon-unused';        if ('desc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_desc . "\" />";
        } elseif ('asc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_asc . "\" />";
        } elseif ('' != $this->Ini->Label_sort) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort . "\" />";
        } else {
            return '';
        }
    }

    function scIsFieldNumeric($fieldName)
    {
        switch ($fieldName) {
            case "cta_corren_fornec_imp_id":
                return true;
            case "item_proc_compra_id":
                return true;
            case "cod_tipo_movto":
                return true;
            case "vl_lancto_proporc":
                return true;
            case "cod_acao":
                return true;
            case "num_id_tit_ap":
                return true;
            case "situacao_container_id":
                return true;
            case "proc_compra_id":
                return true;
            case "container":
                return true;
            case "fornecedor_id":
                return true;
            case "vl_lancto":
                return true;
        }
        return false;
    }

    function scGetDefaultFieldOrder($fieldName)
    {
        switch ($fieldName) {
            case "cta_corren_fornec_imp_id":
                return 'desc';
            case "data":
                return 'desc';
            case "item_proc_compra_id":
                return 'desc';
            case "cod_tipo_movto":
                return 'desc';
            case "vl_lancto_proporc":
                return 'desc';
            case "cod_acao":
                return 'desc';
            case "num_id_tit_ap":
                return 'desc';
            case "situacao_container_id":
                return 'desc';
            case "proc_compra_id":
                return 'desc';
            case "container":
                return 'desc';
            case "fornecedor_id":
                return 'desc';
            case "vl_lancto":
                return 'desc';
        }
        return 'asc';
    }

