       {
           $opc = "qp";
       }
       $lin_obj .= "       <select id='grid_search_data_hora_cond_" . $ind . "' name='cond_grid_search_data_hora_" . $ind . "' class='" . $this->css_scAppDivToolbarInput . "' style='vertical-align: middle;' onChange='grid_search_hide_input(\"data_hora\", $ind)'>";
       $selected = ($opc == "qp") ? " selected" : "";
       $lin_obj .= "        <option value='qp'" . $selected . ">" . $this->Ini->Nm_lang['lang_srch_like'] . "</option>";
       $selected = ($opc == "np") ? " selected" : "";
       $lin_obj .= "        <option value='np'" . $selected . ">" . $this->Ini->Nm_lang['lang_srch_not_like'] . "</option>";
       $selected = ($opc == "eq") ? " selected" : "";
       $lin_obj .= "        <option value='eq'" . $selected . ">" . $this->Ini->Nm_lang['lang_srch_exac'] . "</option>";
       $selected = ($opc == "ep") ? " selected" : "";
       $lin_obj .= "        <option value='ep'" . $selected . ">" . $this->Ini->Nm_lang['lang_srch_empty'] . "</option>";
       $lin_obj .= "       </select>";
       if ($opc == "nu" || $opc == "nn" || $opc == "ep" || $opc == "ne")
       {
           $display_in_1 = "none";
       }
       else
       {
           $display_in_1 = "''";
       }
       $lin_obj .= "       <span id=\"grid_data_hora_" . $ind . "\" style=\"display:" . $display_in_1 . "\">";
       $lin_obj .= "       <br>";
       $val_cmp = (isset($val[0][0])) ? $val[0][0] : "";
       $data_hora = $val_cmp;
       if ($data_hora != "")
       {
       $data_hora_look = (is_string($data_hora) ? substr($this->Db->qstr($data_hora), 1, -1) : $data_hora); 
       $nmgp_def_dados = array(); 
       $nm_comando = "select distinct data_hora from (SELECT      cta_corren_fornec_imp_id,     fornecedor_id,     data,     cta.item_proc_compra_id as item_proc_compra_id,     historico,     cod_tipo_movto,     vl_lancto, case cod_tipo_movto     when 3 then vl_lancto *      	 (itens.qt_alocada  / itens_ped.qt_comprada)    		   	     else vl_lancto     end as vl_lancto_proporc,     cod_acao,     login,     data_hora,     num_id_tit_ap,     situacao_container_id,     proc_compra_id,    \"nr-container\" as container     FROM      PUB.cta_corren_fornec_imp cta,  pub.\"pp-container\" container,  pub.itens_container itens, pub.itens_proc_compra itens_ped where itens.item_proc_compra_id = cta.item_proc_compra_id and itens.item_proc_compra_id = itens_ped.item_proc_compra_id and itens.container_id = container.\"nr-container\" and container.situacao_container_id  in(" . $_SESSION['sits_entregue'] . ") and fornecedor_id = " . $_SESSION['fornecedor_corrente'] . " and cod_tipo_movto > 2  and  (itens.item_container_id = cta.item_container_id or cta.item_container_id  = 0) and ( num_id_tit_ap = 0 or num_id_tit_ap in (select num_id_tit_ap from pub.pagtos_container pgtos  where pgtos.container_id = container.\"nr-container\") ) ) nm_sel_esp where data_hora = '$data_hora_look'"; 
       $_SESSION['scriptcase']['sc_sql_ult_comando'] = $nm_comando; 
       $_SESSION['scriptcase']['sc_sql_ult_conexao'] = ''; 
      if ($rs = $this->Db->SelectLimit($nm_comando, 10, 0)) 
       { 
          while (!$rs->EOF) 
          { 
            $cmp1 = trim($rs->fields[0]);
            $nmgp_def_dados[] = array($cmp1 => $cmp1); 
             $rs->MoveNext(); 
          } 
          $rs->Close(); 
       } 
       else  
       {  
           if  ($ajax == 'N')
           {  
              $this->Erro->mensagem (__FILE__, __LINE__, "banco", $this->Ini->Nm_lang['lang_errm_dber'], $this->Db->ErrorMsg()); 
              exit; 
           } 
           else
           {  
              echo $this->Db->ErrorMsg(); 
           } 
       } 
       }
       if (isset($nmgp_def_dados[0][$data_hora]))
       {
           $sAutocompValue = $nmgp_def_dados[0][$data_hora];
       }
       else
       {
           $sAutocompValue = $val_cmp;
           $val[0][0]      = $val_cmp;
       }
       $val_cmp = (isset($val[0][0])) ? $val[0][0] : "";
       $lin_obj .= "     <input  type=\"text\" class='sc-js-input " . $this->css_scAppDivToolbarInput . "' id='grid_search_data_hora_val_" . $ind . "' name='val_grid_search_data_hora_" . $ind . "' value=\"" . NM_encode_input($val_cmp) . "\" size=23 alt=\"{datatype: 'text', maxLength: 23, allowedChars: '', lettersCase: '', autoTab: false, enterTab: false}\" style='display: none'>";
       $tmp_pos = (is_string($val_cmp)) ? strpos($val_cmp, "##@@") : false;
       if ($tmp_pos !== false) {
           $val_cmp = substr($val_cmp, ($tmp_pos + 4));
           $sAutocompValue = substr($sAutocompValue, ($tmp_pos + 4));
       }
       $lin_obj .= "     <input class='sc-js-input " . $this->css_scAppDivToolbarInput . "' type='text' id='id_ac_grid_data_hora" . $ind . "' name='val_grid_search_data_hora_autocomp" . $ind . "' size='23' value='" . NM_encode_input($sAutocompValue) . "' alt=\"{datatype: 'text', maxLength: 23, allowedChars: '', lettersCase: '', autoTab: false, enterTab: false}\">";
       $lin_obj .= "       </span>";
       $lin_obj .= "          </div>";
       $lin_obj .= "          <div class='scGridFilterTagListFilterBar'>";
       $lin_obj .= nmButtonOutput($this->arr_buttons, "bapply_appdiv", "closeAllTags();setTimeout(function() {nm_proc_grid_search($ind, 'proc_grid_search', 'grid_search')}, 200);", "closeAllTags();setTimeout(function() {nm_proc_grid_search($ind, 'proc_grid_search', 'grid_search')}, 200);", "grid_search_apply_" . $ind . "", "", "", "", "absmiddle", "", "0px", $this->Ini->path_botoes, "", "", "", "", "", "only_text", "text_right", "", "", "", "", "", "", "");
       $lin_obj .= "          </div>";
       $lin_obj .= "      </div>";
       return $lin_obj;
   }
