function eliminarLanctosCtaCorrenPedImp($pedImp)
{
$_SESSION['scriptcase']['cons_cta_corren_fornec_imp_entregue']['contr_erro'] = 'on';
  
    inserirLogDb('Inicio',__FUNCTION__,__FUNCTION__);
    $aItens = getIDItensProcCompra($pedImp);
