function convertArrayEmInsert($tabela,$aDados,$cpsSemAspas='')
{
$_SESSION['scriptcase']['cons_cta_corren_fornec_imp_entregue']['contr_erro'] = 'on';
  
    $aCampos = array_keys($aDados);
